import{_ as h,I as e,o,c,b6 as i,j as a,J as l,w as t,a as n}from"./chunks/framework.COUcLbTA.js";const P=JSON.parse('{"title":"在线考试与管理系统开发实战","description":"","frontmatter":{},"headers":[],"relativePath":"zh-cn/stage-2/assignments/exam-management-express/index.md","filePath":"zh-cn/stage-2/assignments/exam-management-express/index.md"}'),b={name:"zh-cn/stage-2/assignments/exam-management-express/index.md"},u={style:{margin:"32px 0"}};function k(g,s,m,x,f,_){const p=e("StepBar"),d=e("ClientOnly"),r=e("el-card");return o(),c("div",null,[s[2]||(s[2]=i('<h1 id="在线考试与管理系统开发实战" tabindex="-1">在线考试与管理系统开发实战 <a class="header-anchor" href="#在线考试与管理系统开发实战" aria-label="Permalink to “在线考试与管理系统开发实战”">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to “概述”">​</a></h2><p>本实战项目要求你围绕一份真实的 PRD，从零完成一个在线考试与管理系统。这个项目的特别之处在于它包含多个角色（学生和管理员），每个角色看到的页面和能执行的操作不同。你将使用 Express 构建后端，实现完整的考试业务链路。</p><p>这是 Stage 2 的综合实战环节。多角色权限系统在实际工作中非常常见，掌握这种模式后，你能够应对教培、SaaS、后台管理等各类业务场景。</p><h2 id="前置知识" tabindex="-1">前置知识 <a class="header-anchor" href="#前置知识" aria-label="Permalink to “前置知识”">​</a></h2><p>在开始本项目之前，你应该已经掌握以下内容：</p><ul><li>前端页面设计与组件库使用（<a href="./../../frontend/ui-design/">UI 设计</a>、<a href="./../../frontend/modern-component-library/">现代组件库</a>）</li><li>后端接口设计与开发（<a href="./../../backend/ai-interface-code/">接口代码编写</a>）</li><li>数据库基础与 Supabase（<a href="./../../backend/database-supabase/">从数据库到 Supabase</a>）</li><li>Git 工作流与部署（<a href="./../../backend/git-workflow/">Git 和 GitHub</a>、<a href="./../../backend/zeabur-deployment/">部署 Web 应用</a>）</li></ul><h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to “学习目标”">​</a></h2><p>完成本实战后，你将能够：</p><ol><li>阅读并理解一份真实的 PRD，从中提取开发任务清单</li><li>设计多角色系统的权限控制和页面路由</li><li>使用 Express 实现完整的后端 API</li><li>实现考试、提交、自动判分的业务链路</li><li>完成端到端联调，交付一个可演示的业务系统原型</li></ol><h2 id="项目简介" tabindex="-1">项目简介 <a class="header-anchor" href="#项目简介" aria-label="Permalink to “项目简介”">​</a></h2><p>你要构建的产品是一个在线考试与管理系统，包含三个子系统：</p><table tabindex="0"><thead><tr><th>子系统</th><th>职责</th></tr></thead><tbody><tr><td><strong>官网前台</strong></td><td>平台介绍、登录入口</td></tr><tr><td><strong>学生端</strong></td><td>考试列表、答题、提交、成绩查看</td></tr><tr><td><strong>管理后台</strong></td><td>题库管理、考试管理、提交记录、成绩统计</td></tr></tbody></table><p>后端使用 Express，需要支持：登录鉴权、角色权限、考试和题库管理、提交流程与自动判分、成绩和统计管理。</p><div class="tip custom-block"><p class="custom-block-title">PRD 入口</p><p>本项目的需求文档在 GitHub： <a href="https://github.com/datawhalechina/easy-vibe/blob/main/docs/zh-cn/stage-2/assignments/exam-management-express/PRD.md" target="_blank" rel="noreferrer">查看 PRD</a></p></div>',15)),a("div",u,[l(d,null,{default:t(()=>[l(p,{active:0,items:[{title:"需求分析",description:"阅读 PRD，明确角色、页面、考试链路和数据模型"},{title:"搭建骨架",description:"用 AI 生成学生端和管理端页面骨架"},{title:"后端开发",description:"Express 接通登录、考试、提交、判分"},{title:"联调上线",description:"端到端跑通，部署并准备演示"}]})]),_:1})]),s[3]||(s[3]=i(`<h2 id="第一部分-需求分析" tabindex="-1">第一部分：需求分析 <a class="header-anchor" href="#第一部分-需求分析" aria-label="Permalink to “第一部分：需求分析”">​</a></h2><h3 id="_1-1-阅读-prd" tabindex="-1">1.1 阅读 PRD <a class="header-anchor" href="#_1-1-阅读-prd" aria-label="Permalink to “1.1 阅读 PRD”">​</a></h3><p>打开 PRD 文档，重点回答以下问题：</p><ul><li>系统包含哪几个角色？各自能做什么？</li><li>页面清单是否完整？学生端和管理端分别有哪些页面？</li><li>支持哪些题型？每种题型的判分逻辑是什么？</li><li>考试的完整流程是什么？（发布 → 开始 → 作答 → 提交 → 判分 → 查看成绩）</li></ul><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>如果以上问题没有明确答案，不要开始写代码。需求理解不清楚是导致返工的最常见原因。</p></div><h3 id="_1-2-确认系统架构" tabindex="-1">1.2 确认系统架构 <a class="header-anchor" href="#_1-2-确认系统架构" aria-label="Permalink to “1.2 确认系统架构”">​</a></h3><p>根据 PRD 梳理出系统的整体架构：</p><div class="language-mermaid"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prd[&quot;PRD&quot;] --&gt; web[&quot;官网前台&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prd --&gt; student[&quot;学生端&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prd --&gt; admin[&quot;管理后台&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  student --&gt; auth[&quot;鉴权&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  student --&gt; exam[&quot;考试与作答&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  exam --&gt; db[&quot;数据库&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  admin --&gt; question[&quot;题库管理&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  admin --&gt; submission[&quot;提交记录与成绩统计&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  question --&gt; db</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  submission --&gt; db</span></span></code></pre></div><h2 id="第二部分-搭建项目骨架" tabindex="-1">第二部分：搭建项目骨架 <a class="header-anchor" href="#第二部分-搭建项目骨架" aria-label="Permalink to “第二部分：搭建项目骨架”">​</a></h2><h3 id="_2-1-生成前端页面" tabindex="-1">2.1 生成前端页面 <a class="header-anchor" href="#_2-1-生成前端页面" aria-label="Permalink to “2.1 生成前端页面”">​</a></h3><p>提示词参考：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>请基于当前 PRD，帮我生成一个在线考试与管理系统的前端骨架。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>技术栈要求：</span></span>
<span class="line"><span>- Next.js App Router</span></span>
<span class="line"><span>- TypeScript</span></span>
<span class="line"><span>- Tailwind CSS</span></span>
<span class="line"><span>- shadcn/ui</span></span>
<span class="line"><span></span></span>
<span class="line"><span>页面清单：</span></span>
<span class="line"><span>1. 首页 /</span></span>
<span class="line"><span>2. 登录页 /login</span></span>
<span class="line"><span>3. 学生考试列表页 /student/exams</span></span>
<span class="line"><span>4. 学生答题页 /student/exams/[id]</span></span>
<span class="line"><span>5. 学生成绩页 /student/history</span></span>
<span class="line"><span>6. 管理后台首页 /admin</span></span>
<span class="line"><span>7. 考试管理页 /admin/exams</span></span>
<span class="line"><span>8. 题库管理页 /admin/questions</span></span>
<span class="line"><span>9. 提交记录页 /admin/submissions</span></span>
<span class="line"><span></span></span>
<span class="line"><span>要求：</span></span>
<span class="line"><span>- 学生端页面强调清晰、专注、易答题</span></span>
<span class="line"><span>- 管理端页面使用侧边栏 + 顶部栏布局</span></span>
<span class="line"><span>- 先使用 mock 数据，不接真实接口</span></span>
<span class="line"><span>- 注意桌面端和移动端的基本可用性</span></span></code></pre></div><h3 id="_2-2-完善学生答题页" tabindex="-1">2.2 完善学生答题页 <a class="header-anchor" href="#_2-2-完善学生答题页" aria-label="Permalink to “2.2 完善学生答题页”">​</a></h3><p>答题页是学生端的核心页面，重点完善：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>请继续完善学生答题页。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>这是一个在线考试系统的答题页面，需要包含：</span></span>
<span class="line"><span>- 顶部显示考试标题、倒计时、已答题数量</span></span>
<span class="line"><span>- 中间显示题干和选项</span></span>
<span class="line"><span>- 支持单选、判断、简答三种题型</span></span>
<span class="line"><span>- 左侧或顶部有答题卡，显示每道题是否已作答</span></span>
<span class="line"><span>- 点击提交前弹出确认框</span></span>
<span class="line"><span></span></span>
<span class="line"><span>先用 mock 数据实现交互，不接真实接口。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>要求：</span></span>
<span class="line"><span>- 界面简洁，不要像后台表格页</span></span>
<span class="line"><span>- 倒计时要醒目，但不要制造过强压迫感</span></span>
<span class="line"><span>- 有空状态和 loading 状态</span></span></code></pre></div><h3 id="_2-3-完善管理员后台" tabindex="-1">2.3 完善管理员后台 <a class="header-anchor" href="#_2-3-完善管理员后台" aria-label="Permalink to “2.3 完善管理员后台”">​</a></h3><p>管理员后台第一版聚焦三个核心区域：</p><ul><li><strong>考试管理</strong>：创建考试、设置时长、发布状态</li><li><strong>题库管理</strong>：新增题目、编辑题目、按题型筛选</li><li><strong>提交记录</strong>：查看学生提交、分数、时间</li></ul><h3 id="_2-4-验证页面结构" tabindex="-1">2.4 验证页面结构 <a class="header-anchor" href="#_2-4-验证页面结构" aria-label="Permalink to “2.4 验证页面结构”">​</a></h3><p>逐项检查：</p><ul><li>[ ] 学生端和管理端入口是否分开</li><li>[ ] 登录页、考试列表、答题页、成绩页是否完整</li><li>[ ] 管理端题库、考试管理、提交记录页是否可访问</li><li>[ ] 学生端和管理端的页面风格有明显区分</li></ul><h3 id="遇到阻碍" tabindex="-1">遇到阻碍？ <a class="header-anchor" href="#遇到阻碍" aria-label="Permalink to “遇到阻碍？”">​</a></h3><p>如果你在前端搭建阶段卡住，可以回顾这些章节：</p><ul><li><a href="./../../backend/database-supabase/">从数据库到 Supabase</a></li><li><a href="./../../backend/ai-interface-code/">应用后端接口设计与开发</a></li><li><a href="./../../frontend/modern-component-library/">使用现代组件库更新你的界面</a></li></ul><h2 id="第三部分-后端开发" tabindex="-1">第三部分：后端开发 <a class="header-anchor" href="#第三部分-后端开发" aria-label="Permalink to “第三部分：后端开发”">​</a></h2><h3 id="_3-1-登录与权限控制" tabindex="-1">3.1 登录与权限控制 <a class="header-anchor" href="#_3-1-登录与权限控制" aria-label="Permalink to “3.1 登录与权限控制”">​</a></h3><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>请把我当成 0 基础，帮我完成在线考试系统的登录与权限控制。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>后端使用 Express。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>目标：</span></span>
<span class="line"><span>1. 学生和管理员都可以登录</span></span>
<span class="line"><span>2. 登录后返回用户角色</span></span>
<span class="line"><span>3. 学生只能访问 /student/* 相关接口</span></span>
<span class="line"><span>4. 管理员只能访问 /admin/* 相关接口</span></span>
<span class="line"><span>5. 未登录用户访问受保护页面时跳转 /login</span></span>
<span class="line"><span></span></span>
<span class="line"><span>实现要求：</span></span>
<span class="line"><span>- 给出清晰的目录结构建议</span></span>
<span class="line"><span>- 明确说明中间件负责什么</span></span>
<span class="line"><span>- 涉及环境变量的地方不要硬编码</span></span>
<span class="line"><span>- 完成后说明如何验证权限是否生效</span></span></code></pre></div><h3 id="_3-2-考试与题库管理接口" tabindex="-1">3.2 考试与题库管理接口 <a class="header-anchor" href="#_3-2-考试与题库管理接口" aria-label="Permalink to “3.2 考试与题库管理接口”">​</a></h3><p>建议按以下模块实现：</p><table tabindex="0"><thead><tr><th>模块</th><th>推荐接口</th></tr></thead><tbody><tr><td>考试管理</td><td><code>GET /api/exams</code>、<code>POST /api/admin/exams</code>、<code>PATCH /api/admin/exams/:id</code></td></tr><tr><td>题库管理</td><td><code>GET /api/admin/questions</code>、<code>POST /api/admin/questions</code></td></tr><tr><td>开始考试</td><td><code>POST /api/submissions/start</code></td></tr><tr><td>提交试卷</td><td><code>POST /api/submissions/:id/submit</code></td></tr><tr><td>成绩记录</td><td><code>GET /api/student/history</code>、<code>GET /api/admin/submissions</code></td></tr></tbody></table><p>提示词参考：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>请帮我为在线考试系统设计并实现 Express API。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>功能范围：</span></span>
<span class="line"><span>- 管理员创建考试</span></span>
<span class="line"><span>- 管理员维护题库</span></span>
<span class="line"><span>- 学生查看已发布考试</span></span>
<span class="line"><span>- 学生开始考试并创建 submission</span></span>
<span class="line"><span>- 学生提交答案后自动判分单选题和判断题</span></span>
<span class="line"><span>- 简答题先标记为待复核</span></span>
<span class="line"><span>- 学生查看自己的历史成绩</span></span>
<span class="line"><span>- 管理员查看所有提交记录</span></span>
<span class="line"><span></span></span>
<span class="line"><span>要求：</span></span>
<span class="line"><span>- 接口命名清晰</span></span>
<span class="line"><span>- 返回统一 JSON 结构</span></span>
<span class="line"><span>- 代码中区分 controller、service、middleware、db 层</span></span>
<span class="line"><span>- 说明每个接口如何测试</span></span></code></pre></div><h3 id="_3-3-判分逻辑" tabindex="-1">3.3 判分逻辑 <a class="header-anchor" href="#_3-3-判分逻辑" aria-label="Permalink to “3.3 判分逻辑”">​</a></h3><p>判分逻辑是考试系统的核心业务规则：</p><ul><li><strong>单选题</strong>：用户答案与标准答案一致则得分</li><li><strong>判断题</strong>：同样可以自动判分</li><li><strong>简答题</strong>：第一版先只保存答案，分数为空，状态为 <code>reviewed = false</code></li></ul><div class="tip custom-block"><p class="custom-block-title">加分项</p><p>如果你想增加 AI 能力，可以让管理员在后台输入&quot;主题 + 难度&quot;，由模型先生成一批候选题，再人工审核后入库。但这属于加分项，不是必须的。</p></div><h2 id="第四部分-联调与上线" tabindex="-1">第四部分：联调与上线 <a class="header-anchor" href="#第四部分-联调与上线" aria-label="Permalink to “第四部分：联调与上线”">​</a></h2><h3 id="_4-1-端到端测试" tabindex="-1">4.1 端到端测试 <a class="header-anchor" href="#_4-1-端到端测试" aria-label="Permalink to “4.1 端到端测试”">​</a></h3><p>至少验证以下场景：</p><ul><li>学生登录 → 查看考试列表 → 开始答题 → 提交 → 查看成绩</li><li>管理员登录 → 创建考试 → 添加题目 → 发布 → 查看提交记录</li></ul><h3 id="_4-2-部署" tabindex="-1">4.2 部署 <a class="header-anchor" href="#_4-2-部署" aria-label="Permalink to “4.2 部署”">​</a></h3><ul><li>前端部署到 Vercel / Zeabur</li><li>Express API 部署到 Zeabur / Railway / Render</li><li>数据库用 Supabase Postgres 或托管 PostgreSQL</li></ul><p>部署前检查：</p><ul><li>[ ] 环境变量是否齐全</li><li>[ ] 前后端 API 地址是否正确</li><li>[ ] 登录态在生产环境是否正常</li><li>[ ] 管理员账号是否能真实访问后台</li><li>[ ] README 是否包含启动、部署、测试说明</li></ul><h2 id="交付物" tabindex="-1">交付物 <a class="header-anchor" href="#交付物" aria-label="Permalink to “交付物”">​</a></h2><p>完成本项目后，你需要提交以下内容：</p><ul><li>[ ] 可访问的线上演示链接</li><li>[ ] 源码仓库链接（含 README）</li><li>[ ] PRD 文档</li><li>[ ] 核心页面截图（首页、学生考试列表、答题页、管理后台）</li><li>[ ] 60 秒演示视频（覆盖学生答题流程和管理员管理流程）</li></ul><p>README 至少包含：项目简介、核心页面说明、技术栈、本地启动步骤、环境变量清单。</p><h2 id="评分标准" tabindex="-1">评分标准 <a class="header-anchor" href="#评分标准" aria-label="Permalink to “评分标准”">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>基本要求</th><th>进阶要求</th></tr></thead><tbody><tr><td>页面完整度</td><td>学生端和管理端主要页面都可访问</td><td>页面风格统一，移动端基本可用</td></tr><tr><td>业务闭环</td><td>学生可登录、参加考试、提交并查看成绩</td><td>管理员可完整创建并发布考试</td></tr><tr><td>数据正确性</td><td>提交答案后能写入数据库，客观题能自动判分</td><td>简答题支持人工复核或 AI 辅助</td></tr><tr><td>权限控制</td><td>学生与管理员访问边界清晰</td><td>服务端接口也有角色校验</td></tr><tr><td>工程交付</td><td>项目可运行、可部署、README 清晰</td><td>有演示视频和测试说明</td></tr></tbody></table><h2 id="提交前检查" tabindex="-1">提交前检查 <a class="header-anchor" href="#提交前检查" aria-label="Permalink to “提交前检查”">​</a></h2>`,51)),l(r,{shadow:"hover",style:{margin:"20px 0","border-radius":"12px"}},{header:t(()=>[...s[0]||(s[0]=[a("div",{style:{"font-weight":"bold","font-size":"16px"}},"提交前最后看一眼",-1)])]),default:t(()=>[s[1]||(s[1]=a("ul",{style:{"list-style-type":"none","padding-left":"0"}},[a("li",null,[a("label",null,[a("input",{type:"checkbox",disabled:""}),n(" 首页、登录页、学生端、管理端页面均已完成")])]),a("li",null,[a("label",null,[a("input",{type:"checkbox",disabled:""}),n(" 学生可以正常开始考试并提交答案")])]),a("li",null,[a("label",null,[a("input",{type:"checkbox",disabled:""}),n(" 管理员可以创建考试并查看提交记录")])]),a("li",null,[a("label",null,[a("input",{type:"checkbox",disabled:""}),n(" 客观题分数能够自动计算并写入数据库")])]),a("li",null,[a("label",null,[a("input",{type:"checkbox",disabled:""}),n(" 学生与管理员权限边界已验证")])]),a("li",null,[a("label",null,[a("input",{type:"checkbox",disabled:""}),n(" 项目已部署或具备完整本地运行说明")])])],-1))]),_:1}),s[4]||(s[4]=i('<h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to “参考资料”">​</a></h2><ul><li><a href="./../../frontend/ui-design/">UI 设计</a></li><li><a href="./../../frontend/modern-component-library/">使用现代组件库更新你的界面</a></li><li><a href="./../../backend/database-supabase/">从数据库到 Supabase</a></li><li><a href="./../../backend/ai-interface-code/">大模型辅助编写接口代码与接口文档</a></li><li><a href="./../../backend/git-workflow/">Git 和 GitHub 工作流</a></li><li><a href="./../../backend/zeabur-deployment/">如何部署 Web 应用</a></li></ul>',2))])}const y=h(b,[["render",k]]);export{P as __pageData,y as default};
